mapper.select:
SELECT m.*
FROM merchant m
INNER JOIN merchant_audit ma ON m.id = ma.merchant_id
WHERE 1=1

AND ma.id = (
    SELECT MAX(id)
    FROM merchant_audit
    WHERE merchant_id = m.id
)


    AND ma.audit_status = #{auditStatus}



    AND m.merchant_name LIKE CONCAT('%', #{merchantName}, '%')



    AND m.license_no = #{licenseNo}



    AND m.legal_person LIKE CONCAT('%', #{legalPerson}, '%')



    AND m.phone = #{phone}



    AND m.status = #{status}

ORDER BY m.create_time DESC
